// veld — generated by veld, rewritten when veld changes. Never edit by hand.
//
// The state register.ts keeps across a reload of its own code: the context still owed
// to the next prompt, whether a dialog is on screen and whether it is a question held until answered, and how far the naming nudge got.
declare module 'claude-code' {
  interface PluginState {
    veld: {
      session: {
        contextPending: boolean
        blocked: boolean
        held?: boolean
        launchedAt?: number
        namingPrompt?: boolean
        namingStop?: boolean
      }
    }
  }
}
